package com.quizclash.game.model;

import java.util.List;

/**
 * A quiz question. The same shape is used for the seed file
 * (questions.json) and for questions generated by the AI bot.
 *
 * @param source optional passage from an uploaded document that supports the
 *               answer. Never sent to players; used to ground hints.
 */
public record Question(String id, String question, List<String> options, int correctIndex, String source) {

    public Question {
        if (options == null || options.size() != 4) {
            throw new IllegalArgumentException("A question needs exactly 4 options");
        }
        if (correctIndex < 0 || correctIndex > 3) {
            throw new IllegalArgumentException("correctIndex must be 0..3");
        }
        options = List.copyOf(options);
    }

    public Question(String id, String question, List<String> options, int correctIndex) {
        this(id, question, options, correctIndex, null);
    }
}
